from taf.ul.trs_e2e_fw.lib.oam.oam_interface import setup_oamops
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


def _setup_oam_ops(alias=None):
    if alias is not None:
        admin_alias = alias
    elif not global_vars.setup_admin_called:
        admin_alias = "alias_local"
        setup_oamops(alias=admin_alias)
    else:
        admin_alias = global_vars.admin_alias
    logger.debug("Using admin alias: {}".format(admin_alias))
    return admin_alias
